/**
 * @summary Révoque l'appareil et les sessions ouvertes grâce à lui. `404` pour un appareil inconnu comme
pour celui d'un autre compte (SEC-04).
 */
export const getRevokeTrustedDeviceUrl = (id: string) => {
  return `/api/v1/trusted-devices/${id}`;
};

export const revokeTrustedDevice = async (id: string, options?: RequestInit): Promise<void> => {
  return apiFetch<void>(getRevokeTrustedDeviceUrl(id), {
    ...options,
    method: 'DELETE',
  });
};

export const getRevokeTrustedDeviceMutationOptions = <
  TError = ErrorType<ProblemDetailsDto>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof revokeTrustedDevice>>,
    TError,
    { id: string },
    TContext
  >;
  request?: SecondParameter<typeof apiFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof revokeTrustedDevice>>,
  TError,
  { id: string },
  TContext
> => {
  const mutationKey = ['revokeTrustedDevice'];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof revokeTrustedDevice>>,
    { id: string }
  > = (props) => {
    const { id } = props ?? {};

    return revokeTrustedDevice(id, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

export type RevokeTrustedDeviceMutationResult = NonNullable<
  Awaited<ReturnType<typeof revokeTrustedDevice>>
>;

export type RevokeTrustedDeviceMutationError = ErrorType<ProblemDetailsDto>;

/**
 * @summary Révoque l'appareil et les sessions ouvertes grâce à lui. `404` pour un appareil inconnu comme
pour celui d'un autre compte (SEC-04).
 */
export const useRevokeTrustedDevice = <TError = ErrorType<ProblemDetailsDto>, TContext = unknown>(
  options?: {
    mutation?: UseMutationOptions<
      Awaited<ReturnType<typeof revokeTrustedDevice>>,
      TError,
      { id: string },
      TContext
    >;
    request?: SecondParameter<typeof apiFetch>;
  },
  queryClient?: QueryClient,
): UseMutationResult<
  Awaited<ReturnType<typeof revokeTrustedDevice>>,
  TError,
  { id: string },
  TContext
> => {
  const mutationOptions = getRevokeTrustedDeviceMutationOptions(options);

  return useMutation(mutationOptions, queryClient);
};
